import { joinDescription, type Descriptions } from "./descriptions";

/**
 * Descripciones of the spells of potions, wands and scrolls (tables 7-20 and
 * 7-24 to 7-26, ADR-0002), in 5e terms, by the spell name the tables print.
 * The saving throw named in brackets resists the effect.
 */

const summon = (what: string, level: number) =>
  `Invocas ${what} de poder ${level === 1 ? "menor" : `de nivel ${level}`} que luchan por ti durante 1 minuto (concentración).`;
const naturalAlly = (level: number) => summon("animales o criaturas de la naturaleza", level);
const monster = (level: number) => summon("criaturas de otro plano", level);

const symbol = (effect: string) =>
  `Inscribes un glifo que se activa cuando alguien lo lee, lo toca o pasa junto a él: cada criatura a 60 pies ${effect}.`;

const ENHANCE =
  "Durante 1 hora, una criatura tiene ventaja en las pruebas de";
const enhance = (score: string, extra = "") =>
  `${ENHANCE} ${score}${extra}.`;
const inGroup = (spell: string) => `${spell} Afecta a varias criaturas a 30 pies.`;

const cure = (dice: string) => `Una criatura recupera ${dice} PG.`;
const massCure = (dice: string) =>
  `Hasta seis criaturas a 30 pies recuperan ${dice} PG cada una.`;
const inflict = (dice: string) =>
  `Ataque de conjuro cuerpo a cuerpo: ${dice} de daño necrótico (Constitución, mitad). A un muerto viviente lo cura.`;
const massInflict = (dice: string) =>
  `Hasta seis criaturas a 30 pies reciben ${dice} de daño necrótico cada una (Constitución, mitad). A los muertos vivientes los cura.`;

const hold = (who: string) =>
  `${who} queda paralizado durante 1 minuto (Sabiduría al final de cada uno de sus turnos; concentración).`;

const shadow = (school: string, level: number) =>
  `Imita un conjuro de ${school} de nivel ${level} o inferior hecho de sombras. Quien supere una salvación de Inteligencia lo reconoce como falso y solo sufre una parte de su efecto.`;

const bigbyHand = (effect: string) =>
  `Creas una mano de fuerza Grande a 120 pies que, con una acción adicional, ${effect} durante 1 minuto (concentración).`;

const wordOfPower = (hp: number, effect: string) =>
  `Una criatura que veas a 60 pies con ${hp} PG o menos ${effect}, sin salvación.`;

const alignmentWord = (who: string) =>
  `Cada criatura ${who} a 40 pies que te oiga sufre según su poder: queda ensordecida, cegada, paralizada o muere (Carisma para reducirlo). Los extraplanares de ese alineamiento son desterrados.`;

const alignmentAura = (against: string, effect: string) =>
  `Durante 1 minuto, tú y tus aliados a 30 pies tenéis ventaja en las salvaciones y los ataques de criaturas ${against} contra vosotros tienen desventaja; ${effect}`;

const alignmentBlast = (against: string, damage: string, effect: string) =>
  `Una explosión de 20 pies de radio inflige ${damage} a las criaturas ${against} y ${effect} (Sabiduría, mitad y sin efecto). Las neutrales reciben la mitad.`;

const ALIGNMENT_PROTECTION =
  "Durante 10 minutos, los celestiales, elementales, feéricos, infernales, muertos vivientes y criaturas del alineamiento elegido tienen desventaja al atacar a una criatura, y no pueden hechizarla, asustarla ni poseerla.";

