/** Names a potion or wand gives a spell that the scroll tables spell another way. */
const SPELL_ALIASES: Readonly<Record<string, string>> = {
  "Quitar el miedo": "Quitar miedo",
  "Protección contra": "Protección contra el caos/el mal/el bien/la ley",
  "Círculo mágico contra": "Círculo mágico contra el bien/el caos/el mal/la ley",
};

/**
 * The spell behind a row of the potion or wand tables: without "(poción)",
 * the caster level, the random "(tipo)" or "(alineamiento)" and the bonus or
 * amount it carries.
 */
export function spellOf(name: string): string {
  const spell = name
    .replace(/ \((?:poción|aceite|poción o aceite)\)$/, "")
    .replace(/, intensificado \(.*\)$| \(\d+\.°\)$/, "")
    .replace(/ \((?:tipo|alineamiento)\)/, "")
    .replace(/ (?:\+\d|\d+\/magia|\d+)$/, "");
  return SPELL_ALIASES[spell] ?? spell;
}

const POTION = "Quien la bebe, o el objeto o arma que recibe el aceite, obtiene el efecto del conjuro, sin necesidad de concentración:";
const WAND = "Con una acción gastas una carga y lanzas el conjuro con tu CD y tu bonificador de ataque de conjuros; las cargas no se recargan solas. Solo si el conjuro está en tu lista.";
const SCROLL = "Cada conjuro se lanza una vez si está en tu lista de conjuros, y luego se borra del pergamino.";

const withUse = (use: string, spell: string) => {
  const text = SPELL_DESCRIPTIONS[spell];
  return text && `${use}\n${text}`;
};

/** Description of a row of table 7-20 ("Pociones y aceites"). */
export const describePotion = (name: string) => withUse(POTION, spellOf(name));

/** Description of a row of table 7-26 ("Varitas"). */
export const describeWand = (name: string) => withUse(WAND, spellOf(name));

/** Description of a scroll: how it is used, then each spell it holds. */
export function describeScroll(spells: readonly string[]): string | undefined {
  const lines = [...new Set(spells)].flatMap((spell) => {
    const text = SPELL_DESCRIPTIONS[spell];
    return text ? [`${spell}: ${text}`] : [];
  });
  return lines.length > 0 ? joinDescription([SCROLL, ...lines]) : undefined;
}
